import math

def dew_or_frost_point(x_gkg: float, p_pa: float) -> float:
    if x_gkg <= 0 or p_pa <= 0:
        raise ValueError("The water loading (x_gkg) and total pressure (p_pa) must be positive.")

    # Convert x from g/kg to kg/kg
    x_kg_kg = x_gkg / 1000.0

    # Calculate required vapor pressure e
    # e = x * p / (0.622 + x)
    e_target = (x_kg_kg * p_pa) / (0.622 + x_kg_kg)

    def get_f_pt(t: float) -> float:
        return 1.00062 + 3.14e-8 * p_pa + 5.6e-7 * t**2

    def get_es_w(t: float) -> float:
        # Saturation vapor pressure over water
        return 611.2 * math.exp(17.62 * t / (243.12 + t))

    def get_es_i(t: float) -> float:
        # Saturation vapor pressure over ice
        return 611.2 * math.exp(22.46 * t / (272.62 + t))

    # Function to find root using bisection for high reliability
    def solve_bisection(is_ice: bool) -> float:
        # Water range: t > -243.12
        # Ice range: t > -272.62
        # High bound: 500 °C is sufficient for any reasonable atmospheric pressure/loading
        if is_ice:
            low, high = -271.0, 500.0
            es_func = get_es_i
        else:
            low, high = -242.5, 500.0
            es_func = get_es_w

        for _ in range(100):
            mid = (low + high) / 2.0
            if get_f_pt(mid) * es_func(mid) < e_target:
                low = mid
            else:
                high = mid
        return (low + high) / 2.0

    # Step 1: Solve for dew point (water)
    t_dew = solve_bisection(False)

    # Step 2: If dew point is below 0 °C, solve for frost point (ice)
    if t_dew < 0:
        return solve_bisection(True)
    else:
        return t_dew

import math
import re

def evaluate_expr(s: str, variables: dict | None = None) -> float:
    """
    Parses and evaluates a mathematical expression string.
    Supports: Numbers (1.5e-3), +, -, *, /, ^ (right-associative),
    unary +, -, parentheses, sin, cos, sqrt, exp, ln, constants pi, e, and variables.
    """
    if variables is None:
        variables = {}

    # Tokenizer setup
    token_specification = [
        ('NUMBER', r'\d*\.\d+(?:[eE][+-]?\d+)?|\d+\.\d*(?:[eE][+-]?\d+)?|\d+(?:[eE][+-]?\d+)?'),
        ('ID',     r'[a-zA-Z_][a-zA-Z0-9_]*'),
        ('OP',     r'[+\-*/^()]'),
        ('SKIP',   r'[ \t\n]+'),
        ('MISMATCH', r'.'),
    ]
    tok_regex = '|'.join('(?P<%s>%s)' % pair for pair in token_specification)

    tokens = []
    for mo in re.finditer(tok_regex, s):
        kind = mo.lastgroup
        value = mo.group()
        if kind == 'NUMBER':
            tokens.append(('NUMBER', float(value)))
        elif kind == 'ID':
            tokens.append(('ID', value))
        elif kind == 'OP':
            tokens.append(('OP', value))
        elif kind == 'SKIP':
            continue
        else:
            raise ValueError(f"Unexpected character: {value}")

    class Parser:
        def __init__(self, tokens, vars_dict):
            self.tokens = tokens
            self.pos = 0
            self.vars = vars_dict
            self.funcs = {
                'sin': math.sin, 
                'cos': math.cos, 
                'sqrt': math.sqrt, 
                'exp': math.exp, 
                'ln': math.log
            }
            self.consts = {
                'pi': math.pi, 
                'e': math.e
            }

        def peek(self):
            return self.tokens[self.pos] if self.pos < len(self.tokens) else (None, None)

        def consume(self, expected_val=None):
            kind, val = self.peek()
            if expected_val is not None and val != expected_val:
                raise ValueError(f"Expected {expected_val}, got {val}")
            self.pos += 1
            return val

        def parse_expr(self) -> float:
            """Expression: term { (+|-) term }"""
            node = self.parse_term()
            while True:
                kind, val = self.peek()
                if val in ('+', '-'):
                    self.consume()
                    right = self.parse_term()
                    node = node + right if val == '+' else node - right
                else:
                    break
            return node

        def parse_term(self) -> float:
            """Term: unary { (*|/) unary }"""
            node = self.parse_unary()
            while True:
                kind, val = self.peek()
                if val in ('*', '/'):
                    self.consume()
                    right = self.parse_unary()
                    if val == '*':
                        node *= right
                    else:
                        if right == 0:
                            raise ValueError("Division by zero")
                        node /= right
                else:
                    break
            return node

        def parse_unary(self) -> float:
            """Unary: + unary | - unary | power"""
            kind, val = self.peek()
            if val == '+':
                self.consume()
                return self.parse_unary()
            elif val == '-':
                self.consume()
                return -self.parse_unary()
            else:
                return self.parse_power()

        def parse_power(self) -> float:
            """Power: atom [ ^ unary ] (right-associative)"""
            node = self.parse_atom()
            if self.peek()[1] == '^':
                self.consume()
                # Exponent is evaluated via unary to allow 2^-1
                right = self.parse_unary()
                try:
                    res = node ** right
                    # Check for complex results (e.g. (-2)^0.5)
                    if isinstance(res, complex):
                        raise ValueError("Complex result not supported")
                    node = float(res)
                except (ZeroDivisionError, ValueError, TypeError, OverflowError):
                    raise ValueError("Math error")
            return node

        def parse_atom(self) -> float:
            """Atom: number | ID | func(expr) | (expr)"""
            kind, val = self.peek()
            if kind == 'NUMBER':
                return self.consume()
            elif kind == 'ID':
                name = self.consume()
                if name in self.consts:
                    return self.consts[name]
                elif name in self.funcs:
                    self.consume('(')
                    arg = self.parse_expr()
                    self.consume(')')
                    try:
                        res = self.funcs[name](arg)
                        if isinstance(res, complex):
                            raise ValueError("Complex result not supported")
                        return float(res)
                    except (ValueError, ZeroDivisionError, TypeError):
                        raise ValueError("Math error")
                elif name in self.vars:
                    return self.vars[name]
                else:
                    raise ValueError(f"Unknown name: {name}")
            elif val == '(':
                self.consume('(')
                node = self.parse_expr()
                self.consume(')')
                return node
            else:
                raise ValueError(f"Unexpected token: {val}")

    parser = Parser(tokens, variables)
    result = parser.parse_expr()
    if parser.pos < len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return float(result)

def rx_fullmatch(pattern: str, text: str) -> bool:
    class State:
        def __init__(self):
            self.epsilon_transitions = []
            self.char_transitions = []

    class NFA:
        def __init__(self, start, end):
            self.start = start
            self.end = end

    class Parser:
        def __init__(self, pattern):
            self.pattern = pattern
            self.pos = 0

        def peek(self):
            return self.pattern[self.pos] if self.pos < len(self.pattern) else None

        def consume(self, expected=None):
            char = self.peek()
            if expected and char != expected:
                raise ValueError(f"Expected {expected}")
            if char is None:
                raise ValueError("Unexpected end of pattern")
            self.pos += 1
            return char

        def consume_any(self):
            if self.pos >= len(self.pattern):
                raise ValueError("Unexpected end of pattern")
            char = self.pattern[self.pos]
            if char == '\\':
                self.pos += 1
                if self.pos >= len(self.pattern):
                    raise ValueError("Trailing backslash")
                char = self.pattern[self.pos]
            self.pos += 1
            return char

        def parse_expression(self):
            alternations = [self.parse_sequence()]
            while self.peek() == '|':
                self.consume('|')
                alternations.append(self.parse_sequence())
            if len(alternations) == 1:
                return alternations[0]
            start, end = State(), State()
            for alt_nfa in alternations:
                start.epsilon_transitions.append(alt_nfa.start)
                alt_nfa.end.epsilon_transitions.append(end)
            return NFA(start, end)

        def parse_sequence(self):
            if self.peek() is None or self.peek() in (')', '|'):
                start, end = State(), State()
                start.epsilon_transitions.append(end)
                return NFA(start, end)
            atoms = []
            while self.peek() is not None and self.peek() not in (')', '|'):
                atoms.append(self.parse_quantifier())
            start = State()
            current = start
            for atom_nfa in atoms:
                current.epsilon_transitions.append(atom_nfa.start)
                current = atom_nfa.end
            end = State()
            current.epsilon_transitions.append(end)
            return NFA(start, end)

        def parse_quantifier(self):
            atom_nfa = self.parse_atom()
            op = self.peek()
            if op in ('*', '+', '?'):
                self.consume()
                start, end = State(), State()
                if op == '*':
                    start.epsilon_transitions.extend([atom_nfa.start, end])
                    atom_nfa.end.epsilon_transitions.extend([atom_nfa.start, end])
                elif op == '+':
                    start.epsilon_transitions.append(atom_nfa.start)
                    atom_nfa.end.epsilon_transitions.extend([atom_nfa.start, end])
                elif op == '?':
                    start.epsilon_transitions.extend([atom_nfa.start, end])
                    atom_nfa.end.epsilon_transitions.append(end)
                return NFA(start, end)
            return atom_nfa

        def parse_atom(self):
            char = self.peek()
            if char is None:
                raise ValueError("Unexpected end of pattern")
            if char == '(':
                self.consume('(')
                nfa = self.parse_expression()
                if self.peek() != ')':
                    raise ValueError("Unclosed '('")
                self.consume(')')
                return nfa
            elif char == '[':
                return self.parse_char_class()
            elif char == '.':
                self.consume('.')
                start, end = State(), State()
                start.char_transitions.append((lambda _: True, end))
                return NFA(start, end)
            elif char == '\\':
                val = self.consume_any()
                start, end = State(), State()
                start.char_transitions.append((lambda c, v=val: c == v, end))
                return NFA(start, end)
            elif char in ('*', '+', '?', ')', '|'):
                raise ValueError(f"Unexpected quantifier or control char: {char}")
            else:
                val = self.consume_any()
                start, end = State(), State()
                start.char_transitions.append((lambda c, v=val: c == v, end))
                return NFA(start, end)

        def parse_char_class(self):
            self.consume('[')
            negate = False
            if self.peek() == '^':
                negate = True
                self.consume('^')
            ranges = []
            if self.peek() == ']':
                ranges.append((']', ']'))
                self.consume(']')
            else:
                while self.peek() is not None and self.peek() != ']':
                    start = self.consume_any()
                    if self.peek() == '-' and self.pos < len(self.pattern) and self.pattern[self.pos+1] != ']':
                        self.consume('-')
                        end = self.consume_any()
                        if start > end:
                            raise ValueError(f"Invalid range {start}-{end}")
                        ranges.append((start, end))
                    else:
                        ranges.append((start, start))
                if self.peek() != ']':
                    raise ValueError("Unclosed '['")
                self.consume(']')
            def matcher(c):
                found = any(s <= c <= e for s, e in ranges)
                return (not found) if negate else found
            start, end = State(), State()
            start.char_transitions.append((matcher, end))
            return NFA(start, end)

    parser = Parser(pattern)
    nfa = parser.parse_expression()
    if parser.pos != len(pattern):
        raise ValueError("Unmatched pattern suffix")

    def get_epsilon_closure(states):
        closure = set(states)
        stack = list(states)
        while stack:
            s = stack.pop()
            for target in s.epsilon_transitions:
                if target not in closure:
                    closure.add(target)
                    stack.append(target)
        return closure

    current_states = get_epsilon_closure({nfa.start})
    for char in text:
        next_states = set()
        for s in current_states:
            for predicate, target in s.char_transitions:
                if predicate(char):
                    next_states.add(target)
        current_states = get_epsilon_closure(next_states)
        if not current_states:
            break

    return nfa.end in current_states

import heapq

def k_shortest_paths(graph: dict, src, dst, k: int) -> list[tuple[float, list]]:
    if src == dst:
        return [(0.0, [src])]

    def get_dijkstra(start, end, ex_edges, ex_nodes):
        pq = [(0.0, start)]
        visited_costs = {start: 0.0}
        parents = {start: None}

        while pq:
            cost, u = heapq.heappop(pq)
            if cost > visited_costs.get(u, float('inf')):
                continue
            if u == end:
                path = []
                curr = end
                while curr is not None:
                    path.append(curr)
                    curr = parents[curr]
                return (cost, path[::-1])

            if u in graph:
                for v, weight in graph[u].items():
                    if v in ex_nodes or (u, v) in ex_edges:
                        continue
                    new_cost = cost + weight
                    if new_cost < visited_costs.get(v, float('inf')):
                        visited_costs[v] = new_cost
                        parents[v] = u
                        heapq.heappush(pq, (new_cost, v))
        return None

    A = []
    B = []
    B_paths = set()

    first_res = get_dijkstra(src, dst, set(), set())
    if not first_res:
        return []

    A.append(first_res)

    for _ in range(1, k):
        prev_path = A[-1][1]
        for i in range(len(prev_path) - 1):
            spur_node = prev_path[i]
            root_path = prev_path[:i+1]

            ex_edges = set()
            for _, p_in_a in A:
                if len(p_in_a) > i + 1 and p_in_a[:i+1] == root_path:
                    ex_edges.add((p_in_a[i], p_in_a[i+1]))

            ex_nodes = set(root_path[:-1])

            res_spur = get_dijkstra(spur_node, dst, ex_edges, ex_nodes)
            if res_spur:
                spur_cost, spur_path = res_spur
                total_path = root_path[:-1] + spur_path

                total_cost = 0.0
                for idx in range(len(total_path) - 1):
                    u_node, v_node = total_path[idx], total_path[idx+1]
                    total_cost += graph[u_node][v_node]

                path_tuple = tuple(total_path)
                if not any(p[1] == total_path for p in A) and path_tuple not in B_paths:
                    heapq.heappush(B, (total_cost, total_path))
                    B_paths.add(path_tuple)

        if not B:
            break

        next_best = heapq.heappop(B)
        B_paths.remove(tuple(next_best[1]))
        A.append(next_best)

    return A

def crc_generic(data: bytes, width: int, poly: int, init: int, refin: bool, refout: bool, xorout: int) -> int:
    if not (1 <= width <= 64):
        raise ValueError("width must be between 1 and 64")

    mask = (1 << width) - 1
    crc = init & mask

    # Convert bytes to a bit stream
    # We first create the bit stream in MSB-first order for each byte
    bits = []
    for byte in data:
        for i in range(7, -1, -1):
            bits.append((byte >> i) & 1)

    # If RefIn is True, the entire input bit stream is reversed
    if refin:
        bits.reverse()

    # Standard MSB-first CRC bit-by-bit processing
    for bit in bits:
        msb = (crc >> (width - 1)) & 1
        crc = (crc << 1) & mask
        if msb ^ bit:
            crc ^= poly

    # If RefOut is True, reflect the bits of the resulting CRC register
    if refout:
        reflected_crc = 0
        for i in range(width):
            if (crc >> i) & 1:
                reflected_crc |= (1 << (width - 1 - i))
        crc = reflected_crc

    return (crc ^ xorout) & mask
